'use strict';
let data,selected='',view='mine',visible=50;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=s=>{try{let u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};const norm=s=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'').replace(/ggdb|ggs/g,'goldengoose');const money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);let local=[];try{local=JSON.parse(localStorage.getItem('daves-finds-v1')||'[]');if(!Array.isArray(local))local=[]}catch{}
const preferred={Autry:/autry/i,'Axel Arigato':/axel|arigat/i,AMI:/\bami\b/i,'Nike P-6000':/p[ -]?6000/i,'Adidas Spezial':/spezial/i,'Adidas Campus':/campus/i,'Golden Goose':/golden\s*goose|\bggs\b|\bggdb\b/i,Birkenstock:/birken/i,Margiela:/margiela|marglela/i,Rolex:/rolex/i,Cartier:/cartier/i,'New Balance':/new\s*balance|\bnb\s*\d/i,'Adidas Samba':/samba/i,'ASICS Kayano':/kayano/i,'Adidas Evo':/evo\s*sl/i,Loafer:/loafer|summer\s*walk/i};
const shopOf=p=>{try{return new URL(p.url).hostname.replace(/^www\./,'').split('.').slice(-2).join('.')}catch{return ''}};
const prefMatch=p=>Object.values(preferred).some(rx=>rx.test(p.name));
function render(reset=true){if(reset!==false)visible=50;let q=norm($('#query').value),src=$('#source').value,shop=$('#shop').value;let list=[...data.products,...local].filter(p=>(view==='all'||prefMatch(p))&&(!selected||(preferred[selected]?preferred[selected].test(p.name):p.brand===selected))&&(!src||p.source===src)&&(!shop||shopOf(p)===shop)&&(!q||norm(p.name+' '+p.brand+' '+p.location).includes(q)));list.sort((a,b)=>{let order=$('#sort').value;if(order==='name')return a.name.localeCompare(b.name);if(a.euro===null)return b.euro===null?0:1;if(b.euro===null)return -1;return order==='low'?a.euro-b.euro:b.euro-a.euro});$('#count').textContent=list.length+' Treffer';$('#empty').hidden=!!list.length;$('#more').hidden=list.length<=visible;$('#more').textContent='Weitere '+Math.min(50,list.length-visible)+' anzeigen';$('#rows').innerHTML=list.slice(0,visible).map(p=>{let s=data.sources.find(s=>s.id===p.source);return `<tr><td>${p.image&&(safe(p.image)||/^imports\/assets\/[a-f0-9]+\.(png|jpe?g|webp|gif)$/.test(p.image))?`<img class="productimage" src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" referrerpolicy="no-referrer">`:'<span class="noimage">Kein Bild</span>'}</td><td>${esc(p.name)}<small>${esc(p.brand)}</small></td><td>${(Number.isFinite(p.euro)?money(p.euro):"Preis offen")}<small>${esc(p.raw||'Eigene Angabe')}${p.rateDate?' · Kurs '+esc(p.rateDate):''}</small></td><td>${s?.url?`<a href="${esc(safe(p.sourceUrl||s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a>`:esc(s?.name||'Eigener Eintrag')}<small>${esc(p.location)} · ${esc(shopOf(p))} · ${esc(p.status)}</small></td><td>${safe(p.url)?`<a class="productlink" href="${esc(safe(p.url))}" target="_blank" rel="noopener noreferrer">Produkt ↗</a>`:'Kein Link'}</td></tr>`}).join('');document.querySelectorAll('[data-brand]').forEach(b=>{b.classList.toggle('active',b.dataset.brand===selected);b.setAttribute('aria-pressed',b.dataset.brand===selected)});}
Promise.resolve(window.findsCatalog).then(d=>{data=d;d.products.forEach(p=>{let b=Object.keys(preferred).find(b=>preferred[b].test(p.name));if(b)p.brand=b;});$('#notice').textContent=d.note;$('#date').textContent='Stand '+d.updated;$('#stats').innerHTML=`<span>${d.sources.length} Quellen</span><span>${d.products.length} erfasste Produktlinks</span><span>Importstand je Quelle</span>`;$('#brands').innerHTML=['Alle',...d.brands].map(b=>`<button data-brand="${b==='Alle'?'':esc(b)}">${esc(b)}</button>`).join('');$('#shop').innerHTML='<option value="">Alle Webseiten</option>'+[...new Set(d.products.map(shopOf).filter(Boolean))].sort().map(host=>`<option value="${esc(host)}">${esc(host)}</option>`).join('');$('#source').innerHTML+=[...d.sources,{id:'local',name:'Eigene Einträge'}].map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$('#addbrand').innerHTML=d.brands.map(b=>`<option>${esc(b)}</option>`).join('');$('#sourcecards').innerHTML=d.sources.map(s=>`<div class="sourcecard">${s.url?`<a href="${esc(safe(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`:esc(s.name)}<div class="status">${esc(s.status)}</div></div>`).join('');$('#brands').addEventListener('click',e=>{if(e.target.dataset.brand!==undefined){selected=e.target.dataset.brand;render()}});for(let id of ['query','source','shop','sort'])$('#'+id).addEventListener('input',render);$('#more').onclick=()=>{visible+=50;render(false)};for(const mode of ['all','mine'])$('#view-'+mode).onclick=()=>{view=mode;selected='';for(const m of ['all','mine']){$('#view-'+m).classList.toggle('active',m===view);$('#view-'+m).setAttribute('aria-pressed',m===view)}$('#viewhint').textContent=view==='all'?'Alle erkannten Produkte, auch außerhalb deiner Marken.':'Deine Marken und Modelle aus allen erfassten Listen.';render()};$('#reports').innerHTML=(d.importReports||[]).map(r=>`<p><strong>${esc(r.source)}</strong>: ${r.status==='ok'?esc(r.products)+' Produkte · '+esc(r.missing_images||0)+' ohne Bild · '+esc(r.missing_prices||0)+' ohne Preis · '+esc(r.unmatched_links||0)+' Links ohne zugeordnete Produktzeile':esc(r.reason)}</p>`).join('')||'Noch kein Importbericht vorhanden.';render();}).catch(()=>{$('#empty').hidden=false;$('#empty').textContent='Die Daten konnten nicht geladen werden. Bitte die Seite erneut laden.'});
$('#add').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),url=safe(f.get('url'));if(!url)return;local.push({id:'local-'+Date.now(),brand:f.get('brand'),name:f.get('name'),euro:Number(f.get('price')),url,source:'local',location:f.get('location'),status:'Eigene Angabe',checked:new Date().toISOString().slice(0,10)});try{localStorage.setItem('daves-finds-v1',JSON.stringify(local));$('#saved').textContent='Auf diesem Gerät gespeichert.'}catch{$('#saved').textContent='Nur bis zum Neuladen verfügbar. Bitte exportieren.'}e.target.reset();render()});
$('#export').onclick=()=>{if(!data)return;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({...data,products:[...data.products,...local]},null,2)],{type:'application/json'}));a.download='daves-finds.json';a.click();URL.revokeObjectURL(a.href)};
$('#import').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error();let d=JSON.parse(await f.text());if(!Array.isArray(d.products)||!Array.isArray(d.sources)||!Array.isArray(d.brands)||!d.products.every(p=>typeof p.name==='string'&&(p.euro===null||(Number.isFinite(p.euro)&&p.euro>=0))&&safe(p.url)))throw Error();let additions=d.products.filter(p=>!data.products.some(x=>x.url===p.url)&&!local.some(x=>x.url===p.url)).map(p=>({...p,source:'local',status:'Importierte Angabe'}));local.push(...additions);localStorage.setItem('daves-finds-v1',JSON.stringify(local));$('#importstatus').textContent=additions.length+' neue Einträge auf diesem Gerät importiert.';render()}catch{$('#importstatus').textContent='Import fehlgeschlagen. Bitte eine gültige exportierte Sammlung auswählen.'}};
